def _lesson(stage:int, number:int, row:tuple)->dict:
    title, task, kind, target, expected=row
    return {"id":f"{stage}-{number}","stage_id":stage,"number":number,"title":title,
      "summary":task,"theory":f"{title} — практический навык работы с книгой Excel. Сначала определите структуру данных, затем выполните операцию и проверьте результат, не подменяя исходные значения случайными данными.",
      "task":task,"checks":[{"kind":kind,"target":target,"expected":expected}],
      "steps":["Изучите пример и цель урока.","Выполните задание в учебной книге.","Проверьте формулу, диапазон или операцию.","Нажмите «Проверить работу».","Исправьте отмеченную ошибку и завершите урок."]}

LESSONS=[_lesson(s,i,row) for s,rows in TOPICS.items() for i,row in enumerate(rows,1)]
def get_curriculum(): return {"title":"Excel Academy Studio Pro","total_lessons":72,"available_lessons":72,"stages":deepcopy(STAGES),"lessons":deepcopy(LESSONS)}
def get_lesson(lesson_id): return next((deepcopy(x) for x in LESSONS if x["id"]==lesson_id),None)
